export const MOCK_APPLIED_JOBS: Job[] = [];

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Job, ViewState } from './types';
import { searchAndParseJobs, analyzeJob, generateApplicationKit, enrichJob } from './services/geminiService';
import { initFirebase, subscribeToJobs, addOrUpdateJob, updateJobStatus, deleteJob, saveAnalysis, addManualJob } from './services/firebase';
import { DEFAULT_FIREBASE_CONFIG } from './constants';
import JobCard from './components/JobCard';
import StatsPanel from './components/StatsPanel';
import KanbanBoard from './components/KanbanBoard';
import CVEditor from './components/CVEditor';
import JobDetailModal from './components/JobDetailModal';
import AddLinkModal from './components/AddLinkModal';
import { Layers, Moon, Sun, LogOut, Settings, X, Archive, Trash2, Plus, Search, ArrowDownUp, Sparkles, Radar } from 'lucide-react';

const App: React.FC = () => {
  // Navigation & Data
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.DASHBOARD);
  const [activeTab, setActiveTab] = useState<'new' | 'saved' | 'archived'>('new');
  const [allJobs, setAllJobs] = useState<Job[]>([]);
  const [targetJobId, setTargetJobId] = useState<string | null>(null);

  // Search Configuration
  const [searchRole, setSearchRole] = useState('Senior UX Designer');
  const [searchLocation, setSearchLocation] = useState('United Kingdom');
  const [isSearchSettingsOpen, setIsSearchSettingsOpen] = useState(false);
  const searchSettingsRef = useRef<HTMLDivElement>(null);

  // VISUAL TELEMETRY (Scouting Drone)
  const [scoutState, setScoutState] = useState<'idle' | 'initializing' | 'scanning' | 'analyzing' | 'complete'>('idle');
  const [telemetryLogs, setTelemetryLogs] = useState<string[]>([]);

  // Multi-Select
  const [isSelectMode, setIsSelectMode] = useState(false);
  const [selectedJobIds, setSelectedJobIds] = useState<Set<string>>(new Set());

  // Theme State
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return localStorage.getItem('theme') === 'dark' || 
               (!localStorage.getItem('theme') && window.matchMedia('(prefers-color-scheme: dark)').matches);
    }
    return false;
  });

  // Profile Menu State
  const [isProfileMenuOpen, setIsProfileMenuOpen] = useState(false);
  const profileMenuRef = useRef<HTMLDivElement>(null);

  // Auto-Init Firebase
  const [isDbConnected] = useState(() => initFirebase(DEFAULT_FIREBASE_CONFIG));

  // Filter & Sort
  const [cityFilter, setCityFilter] = useState<string>('All');
  const [industryFilter, setIndustryFilter] = useState<string | null>(null);
  const [sortBy, setSortBy] = useState<'date' | 'score'>('date');

  // Status
  const [analyzingCount, setAnalyzingCount] = useState(0);

  // Modal
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [initialModalTab, setInitialModalTab] = useState<'brief' | 'strategy'>('brief');
  const [isAddLinkOpen, setIsAddLinkOpen] = useState(false);

  // Theme Effect
  useEffect(() => {
      if (darkMode) {
          document.documentElement.classList.add('dark');
          localStorage.setItem('theme', 'dark');
      } else {
          document.documentElement.classList.remove('dark');
          localStorage.setItem('theme', 'light');
      }
  }, [darkMode]);

  // Click Outside Profile/Search Menu
  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (profileMenuRef.current && !profileMenuRef.current.contains(event.target as Node)) {
              setIsProfileMenuOpen(false);
          }
          if (searchSettingsRef.current && !searchSettingsRef.current.contains(event.target as Node)) {
              setIsSearchSettingsOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (isDbConnected) {
      const unsubscribe = subscribeToJobs((jobs) => {
        setAllJobs(jobs);
      });
      return () => unsubscribe();
    }
  }, [isDbConnected]);

  const addTelemetry = (log: string) => {
      setTelemetryLogs(prev => [...prev.slice(-5), `> ${log}`]);
  };

  const fetchJobs = async () => {
    if (!isDbConnected) return;

    // Start Scouting Drone Sequence
    setScoutState('initializing');
    setTelemetryLogs([]);
    addTelemetry(`System Initialized. User: Vyom Pathroliya`);
    await new Promise(r => setTimeout(r, 600));

    addTelemetry(`Target Protocol: ${searchRole}`);
    addTelemetry(`Geo-Fence: ${searchLocation}`);
    setScoutState('scanning');

    try {
      addTelemetry(`Triangulating salary bands...`);
      const foundJobs = await searchAndParseJobs(searchRole, searchLocation);
      addTelemetry(`Filtering low-seniority noise...`);

      const jobsToAnalyze: Job[] = [];
      for (const job of foundJobs) {
        const docId = `${job.title}_${job.company}`.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 100);
        const existing = allJobs.find(j => j.id === docId);
        const jobWithTimestamp = { ...job, scoutedAt: Date.now() };
        await addOrUpdateJob(jobWithTimestamp);
        if (!existing || !existing.analysis) {
           jobsToAnalyze.push({ ...jobWithTimestamp, id: docId });
        }
      }

      if (jobsToAnalyze.length > 0) {
          setScoutState('analyzing');
          addTelemetry(`Cross-referencing Fintech keywords...`);
          addTelemetry(`Analyzing commute risk factors...`);
          await analyzeNewJobs(jobsToAnalyze);
      } else {
          addTelemetry(`No new un-analyzed targets.`);
      }

      addTelemetry(`Mission Complete.`);
      await new Promise(r => setTimeout(r, 800));
      setScoutState('idle');

    } catch (error) { 
        console.error(error); 
        addTelemetry(`ERR: Signal Lost.`);
        setTimeout(() => setScoutState('idle'), 2000);
    }
  };

  const analyzeNewJobs = async (jobs: Job[]) => {
      setAnalyzingCount(prev => prev + jobs.length);
      for (const job of jobs) {
        try {
            addTelemetry(`Analyzing fit: ${job.company}...`);
            const analysis = await analyzeJob(job);
            await saveAnalysis(job.id, analysis);
        } catch (e) {
            console.error(`Analysis failed for job ${job.id}`, e);
        } finally {
            setAnalyzingCount(prev => Math.max(0, prev - 1));
            // Artificial delay to make the telemetry readable (Game Design)
            await new Promise(resolve => setTimeout(resolve, 600)); 
        }
      }
      setAnalyzingCount(0);
  };

  const handleOpenDetail = (job: Job, tab: 'brief' | 'strategy' = 'brief') => {
    setSelectedJob(job);
    setInitialModalTab(tab);
    setModalOpen(true);
  };

  const handleUpdateJob = async (updatedJob: Job) => {
      await addOrUpdateJob(updatedJob);
      if (selectedJob && selectedJob.id === updatedJob.id) {
          setSelectedJob(updatedJob);
      }
  };

  const handleReAnalyzeJob = async (job: Job) => {
      try {
          const analysis = await analyzeJob(job);
          await saveAnalysis(job.id, analysis);
          const updatedJob = { ...job, analysis };
          setSelectedJob(updatedJob);
          setAllJobs(prev => prev.map(j => j.id === job.id ? updatedJob : j));
      } catch (e) {
          console.error("Re-analysis failed", e);
      }
  };

  const handleGenerateKit = async (job: Job) => {
    if (!job.analysis) return;
    const content = await generateApplicationKit(job, job.analysis);
    const updatedAnalysis = { ...job.analysis, strategy: content };
    await saveAnalysis(job.id, updatedAnalysis);
  };

  const toggleJobStatus = (jobId: string, currentStatus: Job['status']) => {
    let newStatus: Job['status'] = 'saved';
    if (currentStatus === 'new') newStatus = 'saved';
    else if (currentStatus === 'saved') newStatus = 'new'; 
    else if (currentStatus === 'archived') newStatus = 'new';
    updateJobStatus(jobId, newStatus!);
  };

  const handleDelete = (jobId: string) => {
    const job = allJobs.find(j => j.id === jobId);
    if (!job) return;
    if (job.status === 'archived') {
        if(confirm("Permanently delete?")) deleteJob(jobId);
    } else {
        updateJobStatus(jobId, 'archived');
    }
  };

  const handleBulkArchive = async () => {
      for (const id of selectedJobIds) {
          await updateJobStatus(id, 'archived');
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const handleBulkDelete = async () => {
      if (!confirm(`Delete ${selectedJobIds.size} jobs permanently?`)) return;
      for (const id of selectedJobIds) {
          await deleteJob(id);
      }
      setSelectedJobIds(new Set());
      setIsSelectMode(false);
  };

  const toggleJobSelection = (id: string) => {
      const next = new Set(selectedJobIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      setSelectedJobIds(next);
  };

  const handleAddManualJob = async (data: { url?: string, text?: string, title?: string, company?: string }) => {
      try {
          if (currentView !== ViewState.DASHBOARD && currentView !== ViewState.KANBAN) {
              setCurrentView(ViewState.DASHBOARD);
              setActiveTab('saved');
          }
          const placeholder = await addManualJob(data);
          if (!placeholder) return;
          setSelectedJob(placeholder);
          setModalOpen(true);
          setInitialModalTab('brief');
          setAnalyzingCount(prev => prev + 1);
          const enrichedDetails = await enrichJob(data);
          const enrichedJob = { ...placeholder, ...enrichedDetails };
          await addOrUpdateJob(enrichedJob);
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? enrichedJob : prev));
          const analysis = await analyzeJob(enrichedJob);
          await saveAnalysis(enrichedJob.id, analysis);
          const analyzedJob = { ...enrichedJob, analysis };
          setSelectedJob(prev => (prev && prev.id === placeholder.id ? analyzedJob : prev));
      } catch (e) {
          console.error("Error adding manual job", e);
      } finally {
          setAnalyzingCount(prev => Math.max(0, prev - 1));
      }
  };

  const handleTailorResume = (jobId: string) => {
    setTargetJobId(jobId);
    setModalOpen(false);
    setCurrentView(ViewState.CV_EDITOR);
  };

  const jobsInCurrentTab = useMemo(() => {
    return allJobs.filter(j => {
        const status = j.status || 'new';
        if (activeTab === 'new') return status === 'new';
        if (activeTab === 'saved') return ['saved', 'applied', 'assessment', 'interview', 'offer'].includes(status);
        if (activeTab === 'archived') return status === 'archived';
        return false;
    });
  }, [allJobs, activeTab]);

  const filteredJobs = useMemo(() => {
      return jobsInCurrentTab.filter(j => {
        const locMatch = cityFilter === 'All' ? true : (cityFilter === 'Other' ? !['edinburgh', 'glasgow', 'remote', 'london', 'manchester'].some(s => j.location.toLowerCase().includes(s)) : j.location.toLowerCase().includes(cityFilter.toLowerCase()));
        if (!locMatch) return false;
        if (industryFilter) {
            const ind = j.analysis?.industry || 'Tech';
            if (ind !== industryFilter) return false;
        }
        return true;
      }).sort((a, b) => {
          if (sortBy === 'score') return (b.analysis?.score || 0) - (a.analysis?.score || 0);
          return (b.scoutedAt || 0) - (a.scoutedAt || 0);
      });
  }, [jobsInCurrentTab, cityFilter, industryFilter, sortBy]);

  const filterOptions = ['All', 'Edinburgh', 'Glasgow', 'Remote', 'London', 'Manchester', 'Other'];

  const targetJobForEditor = useMemo(() => {
      if (!targetJobId) return null;
      return allJobs.find(j => j.id === targetJobId) || null;
  }, [targetJobId, allJobs]);

  return (
    <div className="min-h-screen bg-[#F5F5F7] dark:bg-black pb-20 font-sans overflow-x-hidden transition-colors duration-300">

        {/* SCOUTING DRONE OVERLAY */}
        {scoutState !== 'idle' && (
            <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md">
                <div className="w-[480px] bg-black border border-white/10 rounded-2xl overflow-hidden shadow-2xl flex flex-col relative">
                     {/* Scanner Line */}
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[#0071e3] to-transparent animate-shimmer"></div>

                    <div className="p-8">
                        <div className="flex items-center gap-4 mb-6">
                            <div className="relative">
                                <Radar className="text-[#0071e3] animate-spin-slow" size={40} />
                                <div className="absolute inset-0 bg-[#0071e3]/30 rounded-full blur-xl animate-pulse"></div>
                            </div>
                            <div>
                                <h3 className="text-white font-bold text-xl tracking-tight">Scout Drone Active</h3>
                                <p className="text-[#86868b] text-xs font-mono uppercase tracking-widest mt-1">Sector: {searchLocation}</p>
                            </div>
                        </div>

                        <div className="h-40 font-mono text-xs text-[#00ff00] bg-[#111] rounded-xl p-4 overflow-hidden flex flex-col justify-end shadow-inner mb-6 border border-white/5">
                            {telemetryLogs.map((log, i) => (
                                <div key={i} className="animate-in fade-in slide-in-from-left-2 duration-300 whitespace-nowrap overflow-hidden text-ellipsis opacity-80">
                                    {log}
                                </div>
                            ))}
                            <div className="w-2 h-4 bg-[#00ff00] animate-pulse inline-block ml-1"></div>
                        </div>

                        <div className="flex items-center justify-between text-[#86868b] text-[10px] uppercase tracking-[0.2em]">
                             <span className="flex items-center gap-2">
                                <span className={`w-2 h-2 rounded-full ${scoutState === 'analyzing' ? 'bg-yellow-500 animate-pulse' : 'bg-[#0071e3]'}`}></span>
                                {scoutState} Protocol
                             </span>
                             <span>SECURE CONN</span>
                        </div>
                    </div>
                </div>
            </div>
        )}

        <nav className="fixed top-0 left-0 right-0 h-14 bg-[#1d1d1f]/80 dark:bg-[#1c1c1e]/80 backdrop-blur-xl z-[40] border-b border-white/5 dark:border-white/10 transition-colors duration-300">
            <div className="max-w-[1024px] mx-auto h-full flex items-center justify-between px-6">
                 <div className="flex items-center gap-6">
                     <span className="font-semibold text-base tracking-tight text-white flex items-center gap-2"><Layers size={18} /> Career Studio</span>
                     <div className="hidden sm:flex items-center gap-6 text-[#d2d2d7]">
                         <button onClick={() => { setCurrentView(ViewState.DASHBOARD); setTargetJobId(null); }} className={`transition-colors hover:text-white ${currentView === ViewState.DASHBOARD ? 'text-white' : ''}`}>Discover</button>
                         <button onClick={() => { setCurrentView(ViewState.KANBAN); setTargetJobId(null); }} className={`transition-colors hover:text-white ${currentView === ViewState.KANBAN ? 'text-white' : ''}`}>Pipeline</button>
                         <button onClick={() => setCurrentView(ViewState.CV_EDITOR)} className={`transition-colors hover:text-white ${currentView === ViewState.CV_EDITOR ? 'text-white' : ''}`}>Resume</button>
                     </div>
                 </div>
                 <div className="flex items-center gap-4">
                     {analyzingCount > 0 && (
                        <span className="flex items-center gap-1.5 text-[#0071e3] dark:text-[#0A84FF] font-medium text-[12px]"><Sparkles size={12} className="animate-spin" /> Analyzing...</span>
                     )}
                     <div className="relative" ref={profileMenuRef}>
                        <button onClick={() => setIsProfileMenuOpen(!isProfileMenuOpen)} className="w-8 h-8 rounded-full bg-gray-600 hover:bg-gray-500 text-white flex items-center justify-center text-[10px] font-bold ring-2 ring-white/10 transition-all focus:outline-none">VP</button>
                        {isProfileMenuOpen && (
                            <div className="absolute top-full right-0 mt-2 w-56 bg-white dark:bg-[#1C1C1E] rounded-xl shadow-xl border border-black/5 dark:border-white/10 overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                                <div className="px-4 py-3 border-b border-[#f5f5f7] dark:border-[#38383A]"><p className="text-sm font-semibold text-[#1d1d1f] dark:text-white">Vyom Pathroliya</p><p className="text-xs text-[#86868b] dark:text-[#98989D]">Senior UX Designer</p></div>
                                <div className="p-1">
                                    <button onClick={() => setDarkMode(!darkMode)} className="w-full flex items-center justify-between px-3 py-2 text-sm text-[#1d1d1f] dark:text-[#f5f5f7] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors">
                                        <div className="flex items-center gap-2">{darkMode ? <Moon size={16} /> : <Sun size={16} />}<span>Dark Mode</span></div>
                                        <div className={`w-9 h-5 rounded-full relative transition-colors ${darkMode ? 'bg-[#34C759]' : 'bg-[#E5E5EA]'}`}><div className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-transform ${darkMode ? 'translate-x-4' : 'translate-x-0'}`}></div></div>
                                    </button>
                                    <button className="w-full flex items-center gap-2 px-3 py-2 text-sm text-[#FF3B30] hover:bg-[#F5F5F7] dark:hover:bg-[#2C2C2E] rounded-lg transition-colors"><LogOut size={16} /> Sign Out</button>
                                </div>
                            </div>
                        )}
                     </div>
                 </div>
            </div>
        </nav>

        <div key={currentView} className="view-enter">
            <div className={`pt-24 pb-10 ${currentView === ViewState.KANBAN ? 'w-full' : 'max-w-[1024px] mx-auto px-6'}`}>
                {currentView === ViewState.DASHBOARD && (
                    <>
                        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 mb-12 animate-fade-in-up">
                            <div>
                                <h1 className="text-[48px] md:text-[64px] leading-[1.05] font-semibold text-[#1d1d1f] dark:text-white tracking-tight mb-4 transition-colors">Masterplan your <br/><span className="text-[#86868b] dark:text-[#98989D]">next move.</span></h1>
                                <p className="text-[#1d1d1f] dark:text-[#f5f5f7] text-lg font-medium max-w-lg leading-relaxed transition-colors"><span className="text-[#0071e3] dark:text-[#0A84FF] font-semibold">{allJobs.filter(j => j.status === 'saved').length} opportunities</span> tailored to your experience.</p>
                            </div>
                            <div className="flex gap-3 pb-2 items-center">
                                 <div className="relative" ref={searchSettingsRef}>
                                    <button onClick={() => setIsSearchSettingsOpen(!isSearchSettingsOpen)} className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95" title="Search Settings"><Settings size={18} /></button>
                                    {isSearchSettingsOpen && (
                                        <div className="absolute bottom-full right-0 mb-3 w-72 bg-white dark:bg-[#1C1C1E] rounded-2xl shadow-2xl border border-black/5 dark:border-white/10 p-6 z-50 animate-in fade-in slide-in-from-bottom-2 duration-200">
                                            <div className="flex items-center justify-between mb-4"><h4 className="text-sm font-bold uppercase tracking-wider text-[#86868b]">Search Preferences</h4><button onClick={() => setIsSearchSettingsOpen(false)}><X size={14} /></button></div>
                                            <div className="space-y-4">
                                                <div><label className="block text-[10px] font-bold text-[#86868b] uppercase mb-1">Target Role</label><input value={searchRole} onChange={e => setSearchRole(e.target.value)} className="w-full px-3 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-lg text-sm border-none outline-none focus:ring-1 focus:ring-[#0071e3]" /></div>
                                                <div><label className="block text-[10px] font-bold text-[#86868b] uppercase mb-1">Location</label><input value={searchLocation} onChange={e => setSearchLocation(e.target.value)} className="w-full px-3 py-2 bg-[#f5f5f7] dark:bg-[#2C2C2E] rounded-lg text-sm border-none outline-none focus:ring-1 focus:ring-[#0071e3]" /></div>
                                            </div>
                                        </div>
                                    )}
                                 </div>
                                 <button onClick={fetchJobs} disabled={scoutState !== 'idle'} className={`h-10 px-6 rounded-full bg-[#0071e3] hover:bg-[#0077ED] dark:bg-[#0A84FF] dark:hover:bg-[#409CFF] text-white text-sm font-medium transition-all flex items-center gap-2 ${scoutState !== 'idle' ? 'opacity-70 cursor-not-allowed' : 'hover:scale-105 active:scale-95 shadow-lg shadow-blue-500/20'}`}><Search size={16} /> {scoutState !== 'idle' ? 'Scouting...' : 'Scout Jobs'}</button>
                                 <button onClick={() => setIsAddLinkOpen(true)} className="h-10 w-10 flex items-center justify-center rounded-full bg-[#E8E8ED] hover:bg-[#d2d2d7] dark:bg-[#38383A] dark:hover:bg-[#48484A] text-[#1d1d1f] dark:text-white transition-all hover:scale-105 active:scale-95"><Plus size={18} /></button>
