                            <select value={job.status || 'new'} onChange={handleStatusChange} className="w-full appearance-none px-5 py-4 bg-white dark:bg-apple-card-dark rounded-2xl font-bold text-sm text-apple-text dark:text-white focus:ring-4 focus:ring-apple-blue/5 cursor-pointer outline-none border border-apple-border dark:border-white/5">
                                <option value="saved">Saved</option>
                                <option value="applied">Applied</option>
                                <option value="interview">Interview</option>
                                <option value="offer">Offer</option>
                                <option value="archived">Archived</option>
                            </select>
                        </div>

                        <div>
                            <div className="flex items-center justify-between mb-3">
                                <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray">Match Precision</span>
                                <button onClick={handleReAnalyzeClick} className={`text-apple-blue hover:scale-110 transition-transform ${isAnalyzing ? 'animate-spin' : ''}`}><RotateCw size={14} /></button>
                            </div>
                            <div className="flex items-baseline gap-1">
                                <span className="text-6xl font-bold tracking-tighter text-apple-text dark:text-white">{analysis?.score || '--'}</span>
                                <span className="text-xl font-bold text-apple-gray">%</span>
                            </div>
                        </div>

                        <button onClick={() => onTailorResume?.(job.id)} className="w-full py-5 bg-apple-text dark:bg-white text-white dark:text-apple-text text-sm font-bold rounded-2xl hover:scale-[1.03] transition-all shadow-xl flex items-center justify-center gap-2">
                            <Sparkles size={18} /> War Room Entry
                        </button>
                    </div>

                    <div className="space-y-6 px-4">
                        <div className="flex flex-col gap-1">
                             <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray">Location Precision</span>
                             <p className="font-bold text-apple-text dark:text-white">{job.location}</p>
                        </div>
                        <div className="flex flex-col gap-1">
                             <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-apple-gray">Posted Date</span>
                             <p className="font-bold text-apple-text dark:text-white">{job.postedDate || 'Recent'}</p>
                        </div>
                        <div className="pt-6 border-t border-apple-border dark:border-white/5">
                            <a href={applyUrl} target="_blank" rel="noreferrer" className="flex items-center justify-center gap-2 w-full py-4 bg-apple-blue text-white text-sm font-bold rounded-2xl hover:bg-apple-blue/90 shadow-xl shadow-apple-blue/20">
                                Apply on Company Site <ExternalLink size={16} />
                            </a>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default JobDetailModal;

